/** 每个查询 id 只自动查找一次：loading|none|ready。手动选择后以手动为准。 */
 static final java.util.HashMap<String,String> AUTO=new java.util.HashMap<>();
 void autoPick(){final String q=sourceId();if(q.isEmpty()||picked()!=null||AUTO.containsKey(q))return;AUTO.put(q,"loading");final int token=a.epoch;final JSONArray addons=AddonRegistry.forResource(a.addons==null?new JSONArray():a.addons,"stream",type,q);final String pref=PlaybackPrefs.audio(a.prefs);
  // 0.1.150：插件并行查询，谁先返回就先给出当前最佳片源，后面更好的到了再替换（用户手动选过就不动）；单个插件最多等 SourceCardRules.FETCH_MS。
  new Thread(()->{java.util.ArrayList<String> urls=new java.util.ArrayList<>();for(int i=0;i<addons.length();i++){String base=addons.optJSONObject(i)==null?"":addons.optJSONObject(i).optString("base");if(!base.isEmpty())urls.add(base+"/stream/"+type+"/"+Net.esc(q)+".json");}
   JSONArray all=new JSONArray();final JSONObject[] auto={null};java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newFixedThreadPool(SourceCardRules.poolSize(urls.size()));
   try{java.util.concurrent.ExecutorCompletionService<JSONArray> done=new java.util.concurrent.ExecutorCompletionService<>(pool);for(String url:urls)done.submit(()->StremioStreams.fetch(url,SourceCardRules.FETCH_MS));
    long end=System.nanoTime()+java.util.concurrent.TimeUnit.MILLISECONDS.toNanos(SourceCardRules.FETCH_MS+2000);
    for(int n=0;n<urls.size();n++){long left=end-System.nanoTime();java.util.concurrent.Future<JSONArray> f=left>0?done.poll(left,java.util.concurrent.TimeUnit.NANOSECONDS):null;if(f==null)break;JSONArray r;try{r=f.get();}catch(Exception failed){continue;}if(r.length()==0)continue;
     for(int i=0;i<r.length();i++)all.put(r.opt(i));int best=SourceCardRules.best(all,pref);if(best<0)continue;final JSONObject choice=all.optJSONObject(best);final JSONArray snapshot=new JSONArray();for(int i=0;i<all.length();i++)snapshot.put(all.opt(i));
     a.runOnUiThread(()->{if(a.isFinishing())return;JSONObject current=a.picked.get(q);if(!SourceCardRules.replaceAuto(current,auto[0]))return;a.pickedAll.put(q,snapshot);if(current==choice)return;a.picked.put(q,choice);auto[0]=choice;if(token==a.epoch&&a.detailChrome==this&&a.detailPage&&q.equals(sourceId()))rerender();});}
   }catch(InterruptedException stopped){Thread.currentThread().interrupt();}finally{pool.shutdownNow();}
   a.runOnUiThread(()->{if(a.isFinishing())return;AUTO.put(q,a.picked.get(q)==null?"none":"ready");if(token==a.epoch&&a.detailChrome==this&&a.detailPage&&q.equals(sourceId()))rerender();});},"detail-source-autopick").start();}
