 boolean isFavorite(){JSONArray favorites=a.array("favorites");for(int i=0;i<favorites.length();i++){JSONObject f=favorites.optJSONObject(i);if(f!=null&&id.equals(f.optString("id")))return true;}return false;}
 void favorite(){boolean remove=isFavorite();JSONArray out=new JSONArray(),old=a.array("favorites");for(int i=0;i<old.length();i++){JSONObject f=old.optJSONObject(i);if(f!=null&&!id.equals(f.optString("id")))out.put(f);}if(!remove)try{JSONObject item=new JSONObject(meta.toString());item.put("id",id);item.put("type",type);out.put(item);}catch(Exception ignored){}a.prefs.edit().putString("favorites",out.toString()).apply();Toast.makeText(a,remove?"已取消收藏":"已收藏",Toast.LENGTH_SHORT).show();}
