 void external(JSONObject s){Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(Uri.parse(s.optString("url")),"video/*");i.putExtra("title",meta.optString("name"));JSONObject hints=s.optJSONObject("behaviorHints"),proxy=hints==null?null:hints.optJSONObject("proxyHeaders"),req=proxy==null?null:proxy.optJSONObject("request");String[] pairs=ExternalPlayerRules.pairs(ExternalPlayerRules.sanitize(req));if(pairs.length>0)i.putExtra("headers",pairs);try{a.startActivity(Intent.createChooser(i,"选择播放器"));}catch(Exception e){Toast.makeText(a,"没有可用的外部播放器",Toast.LENGTH_SHORT).show();}}
